  {hash = "2d5329cfca41eb836133a9be1dbd02fb98b40f02b0174d2ccb1abcd3ea1824bf", name = "betterCement", file = "images/betterCement.png", path = "Loenn/betterCement", width = 184, height = 104, template = "spoooky", copyId = ";", background = false, sources = {{mod = "LuckyTestMap", xml = "graphics/atlases/gameplay/tilesets/loenn/bettercement.png"}, {mod = "Mid autumn  festival.zip", xml = "graphics/atlases/gameplay/tilesets/jia/mid autumn festival/bettercement.png"}}, body = "<!-- edge -->\n      <!-- top edge -->\n      <set mask=\"x0x-111-x1x\" tiles=\"6,5; 7,5; 8,5; 9,5\"/>\n      <!-- bottom edge -->\n      <set mask=\"x1x-111-x0x\" tiles=\"6,10; 7,10; 8,10; 9,10\"/>\n      <!-- left edge -->\n      <set mask=\"x1x-011-x1x\" tiles=\"5,6; 5,7; 5,8; 5,9\"/>\n      <!-- right edge -->\n      <set mask=\"x1x-110-x1x\" tiles=\"10,6; 10,7; 10,8; 10,9\"/>\n      <!-- top edge with right inside corner -->\n      <set mask=\"x0x-111-110\" tiles=\"1,10\"/>\n      <!-- top edge with left inside corner -->\n      <set mask=\"x0x-111-011\" tiles=\"2,10\"/>\n      <!-- bottom edge with right inside corner -->\n      <set mask=\"110-111-x0x\" tiles=\"1,11\"/>\n      <!-- bottom edge with left inside corner -->\n      <set mask=\"011-111-x0x\" tiles=\"2,11\"/>\n      <!-- left edge with bottom inside corner -->\n      <set mask=\"x11-011-x10\" tiles=\"10,1\"/>\n      <!-- left edge with top inside corner -->\n      <set mask=\"x10-011-x11\" tiles=\"10,2\"/>\n      <!-- right edge with bottom inside corner -->\n      <set mask=\"11x-110-01x\" tiles=\"11,1\"/>\n      <!-- right edge with top inside corner -->\n      <set mask=\"01x-110-11x\" tiles=\"11,2\"/>\n      <!-- top edge with bottom left and bottom right inner corners -->\n      <set mask=\"x0x-111-010\" tiles=\"8,11\"/>\n      <!-- bottom edge with top left and top right inner corners -->\n      <set mask=\"010-111-x0x\" tiles=\"8,4\"/>\n      <!-- right edge with top left and bottom left inner corners -->\n      <set mask